 57	    private static ReservationReceipt generateReceipt(Reservation reservation, Room room) {
 58	        String title;
 59	        BigDecimal issRetained;
 60	        String text;
 61	
 62	        boolean isCpf = reservation.guest().cpf() != null;
 63	        boolean isCompany = reservation.guest().companyCnpj() != null;
 64	        boolean isPassport = reservation.guest().guestPassport() != null;
 65	
 66	        if (isCpf) {
 67	            title = "Comprovante de reserva";
 68	            issRetained = null;
 69	            text = generateBrazilianReceipt(reservation, room);
 70	        } else if (isCompany) {
 71	            title = "Fatura de hospedagem";
 72	            issRetained = reservation.price().total().multiply(new BigDecimal("0.05"))
 73	                    .setScale(2, java.math.RoundingMode.HALF_EVEN);
 74	            text = generateInvoice(reservation, room, issRetained);
 75	        } else if (isPassport) {
 76	            title = "Booking receipt";
 77	            issRetained = null;
 78	            text = generateBookingReceipt(reservation, room);
 79	        } else {
 80	            throw new IllegalStateException("reservation has no identification");
 81	        }
 82	
 83	        return new ReservationReceipt(
 84	                title,
 85	                reservation.id(),
 86	                reservation.guest().name(),
 87	                reservation.guest().cpf(),
 88	                reservation.guest().companyCnpj(),
 89	                reservation.guest().companyName(),
 90	                reservation.guest().guestPassport(),
 91	                reservation.guest().guestCountry(),
 92	                room.number(),
 93	                room.type(),
 94	                reservation.checkIn(),
 95	                reservation.checkOut(),
 96	                reservation.price().nights(),
 97	                reservation.price().subtotal(),
 98	                reservation.price().discount(),
 99	                reservation.price().total(),
100	                issRetained,
101	                text);
102	    }
103	
104	    private static String generateBrazilianReceipt(Reservation reservation, Room room) {
105	        StringBuilder text = new StringBuilder();
106	        text.append("Comprovante de reserva nº ").append(reservation.id()).append('\n');
107	        text.append("Hóspede: ").append(reservation.guest().name())
108	                .append(" (CPF ").append(reservation.guest().cpf()).append(")\n");
109	        text.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
110	        Price price = reservation.price();
111	        text.append("Entrada: ").append(TextFormat.date(reservation.checkIn()))
112	                .append(" | Saída: ").append(TextFormat.date(reservation.checkOut()))
113	                .append(" | ").append(price.nights()).append(price.nights() == 1 ? " diária" : " diárias").append('\n');
114	        text.append("Diárias: ").append(TextFormat.money(price.subtotal())).append('\n');
115	        if (price.discount().signum() > 0) {
116	            text.append("Desconto: ").append(TextFormat.money(price.discount())).append('\n');
117	        }
118	        text.append("Total: ").append(TextFormat.money(price.total())).append('\n');
119	        return text.toString();
120	    }
